package com.pcguard.exception;
import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { private Map<String,Object> body(HttpStatus s,String error,String msg,HttpServletRequest r){return Map.of("timestamp",Instant.now().toString(),"status",s.value(),"error",error,"message",msg,"path",r.getRequestURI());} @ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) Map<String,Object> missing(NoSuchElementException e,HttpServletRequest r){return body(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage(),r);}@ExceptionHandler(MethodArgumentNotValidException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) Map<String,Object> validation(MethodArgumentNotValidException e,HttpServletRequest r){return body(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",e.getBindingResult().getAllErrors().getFirst().getDefaultMessage(),r);}@ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) Map<String,Object> error(Exception e,HttpServletRequest r){return body(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","An unexpected server error occurred",r);} }
